#!  If using a relative path, that starts from the mg5 directory
# pythia8_path = ./HEPTools/pythia8

#! HepMC3 path
#!  Defines the path to the HepMC3 installation directory (the one
#!  containing the lib and include directories), used when Pythia8 writes
#!  HepMC3 events while it was built against HepMC2 (hepmc_path below is
